namespace {
void num(double x){if(std::isfinite(x))std::cout<<x;else std::cout<<"null";}
void pair(const double* x){std::cout<<'[';num(x[0]);std::cout<<',';num(x[1]);std::cout<<']';}
void boolval(bool x){std::cout<<(x?"true":"false");}
Stream checked(const std::vector<uint8_t>& b,QualityTarget target){const auto actual=native(b);auto s=unpack(b);validateSpectra(s);s.accuracy=3;s.qualityTarget=target;if(s.rate!=8000||s.profile!=4||render(s)!=actual||packV9(s)!=b)throw std::runtime_error("P3 canonical/native/serialization mismatch");return s;}
struct Bits {uint64_t header=104,spectralFlags=0,spectralModes=0,absoluteRice=0,deltaRice=0,scales=0,gains=0,lags=0,mainPulses=0,presence=0,extras=0,padding=0;int repeats=0,absolute=0,delta=0,escapes=0,activeExtras=0,zeroGains=0;};
Bits split(const std::vector<uint8_t>& b,const Stream& s){Bits v;Reader r{b};const int bits=5;for(int f=0;f<int(s.spectra.size());++f){v.spectralFlags++;if(r.get(1)){v.spectralModes++;const bool delta=r.get(1);delta?++v.delta:++v.absolute;for(int k=0;k<10;++k){const auto start=r.at;int q=0;while(q<8&&!r.get(1))++q;if(q==8){r.get(bits+int(delta));++v.escapes;}else r.get(1-int(delta));(delta?v.deltaRice:v.absoluteRice)+=r.at-start;}}else ++v.repeats;for(int half=0;half<2;++half){const int base=f*320+half*160;if(base>=s.samples)break;r.get(5);v.scales+=5;const int gain=r.get(3);v.gains+=3;if(gain){r.get(7);v.lags+=7;}else ++v.zeroGains;for(int group=0;group<4&&base+group*40<s.samples;++group){r.get(10);v.mainPulses+=10;if(b[2]&128){v.presence++;if(r.get(1)){r.get(10);v.extras+=10;++v.activeExtras;}}}}}v.padding=b.size()*8-r.at;if(v.padding>7)throw std::runtime_error("Unexpected final padding");while(r.at<b.size()*8)if(r.get(1))throw std::runtime_error("Nonzero padding");const uint64_t total=v.header+v.spectralFlags+v.spectralModes+v.absoluteRice+v.deltaRice+v.scales+v.gains+v.lags+v.mainPulses+v.presence+v.extras+v.padding;if(total!=b.size()*8)throw std::runtime_error("Bit accounting mismatch");return v;}
void emitBits(const std::vector<uint8_t>& b,const Stream& s){const auto x=split(b,s);std::cout<<"{\"header\":"<<x.header<<",\"spectral_repeat_flags\":"<<x.spectralFlags<<",\"spectral_mode_tags\":"<<x.spectralModes<<",\"absolute_rice\":"<<x.absoluteRice<<",\"delta_rice\":"<<x.deltaRice<<",\"scale\":"<<x.scales<<",\"gain\":"<<x.gains<<",\"lag\":"<<x.lags<<",\"main_pulses\":"<<x.mainPulses<<",\"extra_presence\":"<<x.presence<<",\"extra_symbols\":"<<x.extras<<",\"padding\":"<<x.padding<<",\"spectral_total\":"<<x.spectralFlags+x.spectralModes+x.absoluteRice+x.deltaRice<<",\"repeated_frames\":"<<x.repeats<<",\"absolute_frames\":"<<x.absolute<<",\"delta_frames\":"<<x.delta<<",\"rice_escapes\":"<<x.escapes<<",\"zero_gain_blocks\":"<<x.zeroGains<<",\"active_extras\":"<<x.activeExtras<<",\"total\":"<<b.size()*8<<'}';}
void emitQuality(const Pcm& ref,const Pcm& out,const Stream& s){QualityContext q(ref,true,8000,QualityTarget::Pwm);FullBandContext f(ref,8000,QualityTarget::Pwm);const auto m=q.measure(out);const auto b=f.measure(out);std::cout<<"{\"pcm_sse\":"<<m.quality.error[0]<<",\"pwm_sse\":"<<m.quality.error[1]<<",\"stoi\":";pair(m.quality.stoi);std::cout<<",\"voice\":";pair(m.voice);std::cout<<",\"noise\":";pair(m.noise);std::cout<<",\"fullband_error\":";pair(b.balancedError);std::cout<<",\"fullband_temporal_error\":";pair(b.balancedTemporalError);std::cout<<",\"clipped\":"<<m.clipped<<",\"pitch_within\":["<<m.diagnostic[0].within<<','<<m.diagnostic[1].within<<"],\"pitch_collapsed\":["<<m.diagnostic[0].collapsed<<','<<m.diagnostic[1].collapsed<<"],\"period\":[";num(m.diagnostic[0].period);std::cout<<',';num(m.diagnostic[1].period);std::cout<<"],\"shape\":[";num(m.diagnostic[0].shape);std::cout<<',';num(m.diagnostic[1].shape);std::cout<<"],\"stable\":";boolval(stableLpcStream(s));std::cout<<",\"level_safe\":";boolval(safeSynthesisLevel(s,ref,out));std::cout<<",\"spectrum_safe\":";boolval(safeSynthesisSpectrum(ref,out));std::cout<<'}';}
void emitChanges(const Stream& a,const Stream& b){int indices=0,frames=0,scales=0,lags=0,gains=0,pos=0,amp=0,extras=0;for(size_t f=0;f<a.spectra.size();++f){frames+=a.spectra[f]!=b.spectra[f];for(int k=0;k<10;++k)indices+=a.spectra[f][k]!=b.spectra[f][k];}for(int i=0;i<(a.samples+159)/160;++i){scales+=a.parameters[i][0]!=b.parameters[i][0];lags+=a.parameters[i][1]!=b.parameters[i][1];gains+=a.parameters[i][2]!=b.parameters[i][2];}for(int i=0;i<2*((a.samples+39)/40);++i){pos+=a.pulses[i][0]!=b.pulses[i][0];amp+=a.pulses[i][1]!=b.pulses[i][1];}for(int i=0;i<(a.samples+39)/40;++i)extras+=a.extras[i]!=b.extras[i];std::cout<<"{\"spectral_frames\":"<<frames<<",\"spectral_indices\":"<<indices<<",\"scales\":"<<scales<<",\"lags\":"<<lags<<",\"gains\":"<<gains<<",\"pulse_positions\":"<<pos<<",\"pulse_amplitudes\":"<<amp<<",\"extras\":"<<extras<<",\"pre\":"<<(a.pre!=b.pre)<<",\"brightness\":"<<(a.bright!=b.bright)<<'}';}
}
int main(int argc,char** argv){try{if(argc<2)throw std::runtime_error("encode SOURCE PREFIX pcm|pwm | compare SOURCE BASELINE FIXED PREFIX pcm|pwm");const std::string command=argv[1];std::cout.precision(14);
 if(command=="encode"&&argc==5){const auto reference=pcm(argv[2]);const std::string prefix=argv[3],targetName=argv[4];if(targetName!="pcm"&&targetName!="pwm")throw std::runtime_error("Invalid target");const auto target=targetName=="pcm"?QualityTarget::Pcm:QualityTarget::Pwm;if(reference.empty()||reference.size()>64000||!enc_reserve(reference.size()))throw std::runtime_error("Invalid reference or reserve failure");Stream context;context.accuracy=3;context.qualityTarget=target;context.allowExtras=true;SeedFitStatus status;auto control=fitSeed(reference,4,8000,13926,false,.97,&context,nullptr,&status,target);if(control.samples!=int(reference.size()))throw std::runtime_error("Original control probe failed");control=canonicalAccuracy(control);const int seedBytes=packV9(control).size(),budget=accuracyBudget(reference.size(),3,seedBytes);const auto start=std::chrono::steady_clock::now();const auto cpu=std::clock();AdaptiveReport report;const auto result=encodeAccuracy(reference,3,8000,report,4,nullptr,target);const auto end=std::chrono::steady_clock::now();const auto cpuEnd=std::clock();if(report.error||result.samples!=int(reference.size()))throw std::runtime_error("P3 encode failed");const auto b=packV9(result);const auto out=render(result);if(native(b)!=out)throw std::runtime_error("Encoder/native mismatch");auto transmitted=checked(b,target);save(prefix+".lpx",b);savePcm(prefix+".pcm",out);dump(transmitted,prefix);std::cout<<"{\"samples\":"<<reference.size()<<",\"rate\":8000,\"accuracy\":3,\"target\":\""<<targetName<<"\",\"calls\":4,\"native_model_exact\":true,\"canonical_reserialize_exact\":true,\"bytes\":"<<b.size()<<",\"seed_bytes\":"<<seedBytes<<",\"policy_budget_C\":"<<budget<<",\"headroom_C_minus_output\":"<<budget-int(b.size())<<",\"encode_seconds\":"<<std::chrono::duration<double>(end-start).count()<<",\"encode_cpu_seconds\":"<<double(cpuEnd-cpu)/CLOCKS_PER_SEC<<",\"search\":{\"candidates\":"<<report.candidates<<",\"stages\":"<<report.stages<<",\"spectral_evaluations\":"<<report.jointQuality.lpcSpectralEvaluations<<",\"pulse_evaluations\":"<<report.jointQuality.lpcPulseEvaluations<<",\"synthesized_samples\":"<<report.jointQuality.lpcSynthesizedSamples<<",\"lpc_runs\":"<<report.jointQuality.lpcRuns<<",\"lpc_proposals\":"<<report.jointQuality.lpcProposals<<"},\"bits\":";emitBits(b,transmitted);std::cout<<",\"quality\":";emitQuality(reference,out,transmitted);std::cout<<"}\n";return 0;}
 if(command=="compare"&&argc==7){const auto ref=pcm(argv[2]);const auto aBytes=bytes(argv[3]),bBytes=bytes(argv[4]);const std::string prefix=argv[5],mode=argv[6];if(mode!="pcm"&&mode!="pwm")throw std::runtime_error("Invalid target");const auto target=mode=="pcm"?QualityTarget::Pcm:QualityTarget::Pwm;auto a=checked(aBytes,target),b=checked(bBytes,target);if(a.samples!=b.samples||ref.size()!=size_t(a.samples))throw std::runtime_error("Paired reference mismatch");const auto ap=render(a),bp=render(b);QualityContext q(ref,true,8000,target);FullBandContext full(ref,8000,target);PitchGuardContext pitch(ref,ap,8000,target);const auto am=q.measure(ap),bm=q.measure(bp);unsigned reject=0;if(bBytes.size()>aBytes.size())reject|=1;if(!noRegression(bm.quality,am.quality))reject|=2;for(int p=0;p<qualityPathCount(target);++p)if(!std::isfinite(bm.noise[p])||bm.noise[p]>am.noise[p]+1e-12)reject|=4;if(!full.accepts(full.measure(bp),full.measure(ap)))reject|=8;if(!pitch.accepts(bp))reject|=16;if(bm.clipped>am.clipped)reject|=32;if(!safeSynthesisLevel(b,ref,bp))reject|=64;if(!safeSynthesisSpectrum(ref,bp))reject|=128;if(!stableLpcStream(b))reject|=256;ProfileQualityReport choice;auto selected=selectQualityProposals(a,ref,{&b},choice,true,aBytes.size());if(choice.error)throw std::runtime_error("Complete selector error");const bool selector=packV9(selected)==bBytes&&bBytes!=aBytes;if(bBytes!=aBytes&&!selector)reject|=512;const bool admitted=!reject&&bBytes!=aBytes;const auto& protectedBytes=admitted?bBytes:aBytes;const auto& protectedStream=admitted?b:a;const auto protectedPcm=admitted?bp:ap;save(prefix+".lpx",protectedBytes);savePcm(prefix+".pcm",protectedPcm);dump(protectedStream,prefix);std::cout<<"{\"protected_fix_selected\":";boolval(admitted);std::cout<<",\"raw_changed\":";boolval(aBytes!=bBytes);std::cout<<",\"rejection_bits\":"<<reject<<",\"existing_selector_chose_fix\":";boolval(selector);std::cout<<",\"baseline_byte_ceiling_B0\":"<<aBytes.size()<<",\"raw_size_delta\":"<<int64_t(bBytes.size())-int64_t(aBytes.size())<<",\"raw_changes\":";emitChanges(a,b);std::cout<<",\"protected_changes\":";emitChanges(a,protectedStream);std::cout<<",\"protected_quality\":";emitQuality(ref,protectedPcm,protectedStream);std::cout<<",\"protected_bits\":";emitBits(protectedBytes,protectedStream);std::cout<<",\"native_model_exact\":true}\n";return 0;}
 throw std::runtime_error("Invalid benchmark arguments");}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
